alter table public.provider_signature_operations add constraint provider_signature_operations_org_id_unique unique (organization_id,id);
alter table public.provider_signature_operations add constraint provider_signature_operations_org_fkey foreign key (organization_id) references public.organizations(id) on delete restrict;
alter table public.provider_signature_operations add constraint provider_signature_operations_relationship_fkey foreign key (organization_id,provider_relationship_id,legal_entity_id) references public.provider_relationships(organization_id,id,legal_entity_id) on delete restrict;
alter table public.provider_signature_operations add constraint provider_signature_operations_approval_fkey foreign key (organization_id,approval_request_id,provider_relationship_id,legal_entity_id) references public.provider_approval_requests(organization_id,id,provider_relationship_id,legal_entity_id) on delete restrict;
alter table public.provider_signature_operations add constraint provider_signature_operations_source_fkey foreign key (organization_id,source_document_version_id,provider_relationship_id,legal_entity_id) references public.provider_document_versions(organization_id,id,provider_relationship_id,legal_entity_id) on delete restrict;
alter table public.provider_signature_operations add constraint provider_signature_operations_output_fkey foreign key (organization_id,output_document_version_id,provider_relationship_id,legal_entity_id) references public.provider_document_versions(organization_id,id,provider_relationship_id,legal_entity_id) on delete restrict;
alter table public.provider_signature_operations add constraint provider_signature_operations_signer_not_blank check (btrim(signer_reference) <> '');
alter table public.provider_signature_operations add constraint provider_signature_operations_status_check check (status in ('requested','ready','applied','failed','cancelled'));
alter table public.provider_signature_operations add constraint provider_signature_operations_applied_check check (status <> 'applied' or (applied_at is not null and output_document_version_id is not null and nullif(btrim(coalesce(application_reference,'')),'') is not null));
alter table public.provider_signature_operations add constraint provider_signature_operations_failure_check check (status <> 'failed' or nullif(btrim(coalesce(failure_message,'')),'') is not null);
